page(4,N,T,tag("QUÉ ENCONTRARON")+big("ÉXITO AL PRIMER INTENTO",104)+f'<div style="display:flex;gap:40px"><div style="flex:1;border-top:8px solid {K};padding-top:18px"><div style="font-size:36px;font-weight:800;color:{G}">BOUGIE</div>{big("71,3 %",120,nowrap=True)}</div><div style="flex:1;border-top:8px solid {K};padding-top:18px"><div style="font-size:36px;font-weight:800;color:{G}">FIADOR</div>{big("67,0 %",120,nowrap=True)}</div></div>'+'<div style="font-size:42px;font-weight:800;line-height:1.3">Diferencia de 4,3 puntos (IC 95 %: −8,9 a 17,2; p = 0,53)</div>'+note("Intubación esofágica: 0 con bougie y 5 con fiador (p = 0,059). Tiempo hasta intubar: similar, unos 38–40 s."),**KW),
