page(6,N,T,tag("QUÉ CAMBIA MAÑANA",R)+big("CASI NADA, Y ESO ES ÚTIL",108)+rows(line("Ningún dispositivo demostró ser superior: usa el que mejor domines",True),line("Ten los dos a mano y un plan de rescate dicho en voz alta"),line("Las fracturas faciales predijeron el fallo al primer intento: ahí, máxima preparación"))+note("Un ensayo sin diferencias y con poca potencia no demuestra equivalencia."),**KW),
page(7,N,T,ficha_body("BOUGIE O FIADOR","Paper",[("ESTUDIO","Ensayo BEST. Aleatorizado, un centro, 188 traumatizados graves con vía aérea difícil"),("TÉCNICA","Videolaringoscopio, secuencia diferida con ketamina"),("RESULTADO","Éxito al primer intento: 71,3 % frente a 67,0 %. Sin diferencia significativa",True),("SEGURIDAD","Intubación esofágica 0 frente a 5 (no significativo)"),("LÍMITES","Poca potencia, dos operadores, sin capnografía de onda"),("EN LA GUARDIA","Usa el dispositivo que domines; ten el otro preparado",True)],"Goyal A, et al. Scand J Trauma Resusc Emerg Med 2026;34:171. doi:10.1186/s13049-026-01670-w",size=104,fs=31),ficha="01",fam="PAPER",**KW),
